			var employee_search = $('#username_fax').val();
			// Single Select
			$("#username_fax").autocomplete({

				source: function(request, response) {
					// Fetch data
					$.ajax({
						url: "EMPLOYEE_LOOKUP.php",
						type: 'post',
						dataType: "json",
						data: {
							search: request.term
