	// When the Save button is clicked, I validate the required fields before inserting anything. 
	if (isset($_REQUEST['initialSave'])) {


		//if save form clicked, check if element one is not empty
		if (empty($_POST["element_1"])) {

			$CaseError = 'Please Submit an appropiate value!';
		}

		//check date if empty 

		if (empty($_POST["date"])) {

			$DateError = 'Please select a date!';
		}
		//check element 4 if empty 
		if (empty($_POST["element_4"])) {

			$ErrorErr = 'Please select an Error!';
		}
		//check if username has an IEX 
		if (empty($_POST["populatedEmployeeID"])) {

			$EMPLOYEE_ID_ERROR = 'The username you entered is not linked to an employee ID. Please check your entry and try again.';
		}
		if (empty($_POST["Username_input_fax"])) {

			$EMPLOYEE_ID_ERROR = 'The username you entered is not linked to an employee ID. Please check your entry and try again.';
		} else {
			// If validation passes, I collect the submitted values and prepare the record for the database. 

			$CaseNumber = $_POST["element_1"];
			$dateFull = $_POST["date"];
			$Error1 = $_POST["element_4"];
			$Error2 = $_POST["element_5"];
			$Error3 = $_POST["element_6"];
			$Status = $_POST["element_7"];
			$UserName_Input = $_POST["Username_input_fax"];
			$platform_id = $_POST["platform_id"];
			$populatedEmployeeID_Entry = $_POST["populatedEmployeeID"];
			$Edit_ID_Col = $CaseNumber . $AgentName;
			$ID_Increment = '';
			$originalID ='';
			// Get the next available ID so the new record has a unique identifier.

$resulted = mysqli_query($conn,"SELECT MAX(ID) as Max_ID FROM $DB_TABLE_DEV 


	 /** ID generation does not depend on the case number. **/
/**
	 No auto increment, plus 1 if the record doesnt exist
 	and then if it does exist copy the the id,
  	person that created it, and the time it was created
  
  ID ALREADY EXISTS, JUST COPY WHEN USER HITS EDIT AND PASTE INTO HIDDEN INPUT TO OVERIDE AUTO ID INTO AREA */

	 "
			);
			// If found, set variable
		 

				$row = mysqli_fetch_assoc($resulted);
				$ID_Increment = ($row['Max_ID'] + 1);
				$originalID = 	$ID_Increment;
				// If not found, check what the last Auto ID was and +1 to match the current ID
		 
 
		 
		}

		// Only write to the database when all required validation checks have passed.
		if (empty($CaseError) && (empty($DateError) && (empty($EMPLOYEE_ID_ERROR) && (empty($ErrorErr))))) {





			// Insert the validated record and capture audit details for who created and modified it.
			$query = $conn->query("INSERT INTO $DB_TABLE_DEV 	
			
			    (
				`ID`,
				 `CaseNumber`, 
				 `Status`,
			 	 `DateWorked`, 
				 `userName`,
				 `Platform`,
				 `EMPLOYEE_ID`,
			 	 `ErrorOne`, 
			 	 `ErrorTwo`, 
				 `ErrorThree`,
				 `Domain`,
				 `CreatedBy`,
				 `Created`,
				 `ModifiedByDomain`,
				 `ModifiedBy`,
				 `Modified`
				 )

			VALUES (
			'$originalID',
			'$CaseNumber',
			'$Status',
			'$dateFull',
			'$UserName_Input',
			'$platform_id',
			'$populatedEmployeeID_Entry', 
			'$Error1',
			'$Error2',
			'$Error3',
			'$DomainName',
			'$AgentName',
			CURRENT_TIMESTAMP(),
			'$DomainName',
			'$AgentName',
			CURRENT_TIMESTAMP()
			)");

			echo "<meta http-equiv='refresh' content='3'>";

