			$(this).text(row);

			if ($(this).val() == 'Open') {
				$(this).removeClass('btn-warning');
				$(this).addClass('btn-danger');
				$(this).html('Close');

			} else {

				$(this).removeClass('btn-danger');
				$(this).addClass('btn-warning');
				$(this).html('Open');

			}




			return false;



		});

	});
</script>
