		$(".element_1_Edit").val($CaseNumber);

		$(".element_2_Edit").val($Date_worked);

		$(".CreatedDate_Edit").val(Created_date_add_to_editform);
		// Find the text
		$('.platform_id_form_edit option:selected').text(platform_edit).prop('value', platform_edit);

		$('.element_4_Edit option:selected').text(error_1).prop('value', error_1);
		CreatedBy
