<script>
	// These buttons provide controlled shortcut values for special workflow cases.
$("#FillEscalate").click(function() {


		if ($('#FillEscalate').text() == "Escalation?") {
			$("#FillSpecialQueue").text('Special Queue?')
			$("#FillEscalate").text('Undo?');
			$("#FillEscalate").removeClass('btn-danger');
			$("#FillSpecialQueue").text('Special Queue?');
			$("#FillSpecialQueue").removeClass('btn-warning');
			$(this).addClass('btn-warning');
			$("#username_fax").val('Esc');
			$('#username_fax').prop('readonly', true);
			$("#EMPLOYEE_ID_POP").val('ESCALATION_ID');

		} else {
			$("#FillEscalate").text('Escalation?');
			$("#FillEscalate").removeClass('btn-alert');
			$(this).addClass('btn-danger');
			$("#username_fax").val('');
			$('#username_fax').prop('readonly', false);
			$("#EMPLOYEE_ID_POP").val('');



		}






	});
</script>

<script>
	$("#FillSpecialQueue").click(function() {


		if ($('#FillSpecialQueue').text() == "Special Queue?") {
			$("#FillSpecialQueue").text('Undo?');
			$("#FillEscalate").text('Escalation?');
			$("#FillEscalate").removeClass('btn-alert');
			$("#FillEscalate").addClass('btn-danger');			
			$("#FillSpecialQueue").removeClass('btn-danger');
			$(this).addClass('btn-warning');
			$("#username_fax").val('Special Queue');
			$('#username_fax').prop('readonly', true);
			$("#EMPLOYEE_ID_POP").val('QUEUE_ID');

		} else {
			$("#FillSpecialQueue").text('Special Queue?');
			$("#FillSpecialQueue").removeClass('btn-warning');
			$(this).addClass('btn-info');
			$("#username_fax").val('');
			$('#username_fax').prop('readonly', false);
			$("#EMPLOYEE_ID_POP").val('');



		}






	});
</script>

